def tile_axis(grid, axis):
    # axis 0: frontier rows; 1: frontier cols
    if axis==1: grid=[list(r) for r in zip(*grid)]
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    front={i for i in range(h) if len({v for v in grid[i]})==1 and grid[i][0]!=bg}
    idx=[i for i in range(h) if i not in front]
    segs=[]; cur=[idx[0]]
    for i in idx[1:]:
        if i==cur[-1]+1: cur.append(i)
        else: segs.append(cur); cur=[i]
    segs.append(cur)
    def nz(seg): return sum(grid[i][j]!=bg for i in seg for j in range(w))
    pat=max(segs,key=nz); pl=len(pat)
    out=[row[:] for row in grid]
    for seg in segs:
        for k,i in enumerate(seg):
            out[i]=grid[pat[k%pl]][:]
    if axis==1: out=[list(r) for r in zip(*out)]
    return out

